import { ELECTRIC_ASSEMBLIES } from '../theory/electricAssembly';
import { ELECTRIC_LAB_PARTS, electricAssemblyForPart, guitarLabPart } from '../theory/guitarLabModels';
import type { GuitarLabState, GuitarLabView, GuitarPartId } from '../theory/guitarAnatomy';
import { ElectricLab3D } from './electricLab3d';
import type { GuitarLab3D } from './guitarLab3d';

type Options = ConstructorParameters<typeof GuitarLab3D>[2];
type LabScene = Pick<GuitarLab3D, 'update' | 'setActive' | 'setReducedMotion' | 'hover' | 'setTurntable'
  | 'turntable' | 'cameraView' | 'orbit' | 'zoom' | 'resetView' | 'view' | 'dispose'>;

/** Adapts only the electric choice to the existing Lab controls. */
export class ElectricGuitarLabScene implements LabScene {
  private viewer: ElectricLab3D;
  private state: GuitarLabState;
  private currentView: GuitarLabView = 'three-quarter';
  private ready = false;
  private disposed = false;
  private overlay = document.createElement('div');
  private tip = document.createElement('div');
  private tags = new Map<string, HTMLSpanElement>();

  constructor(private host: HTMLElement, state: GuitarLabState, options: Options) {
    if (state.kind !== 'electric') throw new Error('The recovered scene is for the electric choice only.');
    this.state = state;
    this.overlay.className = 'gl-tags'; this.overlay.setAttribute('aria-hidden', 'true');
    this.tip.className = 'gl-hover'; this.tip.setAttribute('aria-hidden', 'true'); this.tip.hidden = true;
    for (const assembly of ELECTRIC_ASSEMBLIES) {
      const tag = document.createElement('span');
      tag.className = 'gl-tag'; tag.textContent = assembly.name; tag.hidden = true;
      this.tags.set(assembly.id, tag); this.overlay.append(tag);
    }
    try {
      this.viewer = new ElectricLab3D(host, {
        reducedMotion: options.reducedMotion, assembly: true, onUnavailable: options.onUnavailable,
        onAssemblyPick: part => options.onPick(part === null ? null : ELECTRIC_LAB_PARTS[part]),
        onAssemblyHover: (part, point) => {
          const id = part === null ? null : ELECTRIC_LAB_PARTS[part], info = guitarLabPart('electric', id);
          this.tip.hidden = !info || !point;
          this.tip.replaceChildren(...(info ? [Object.assign(document.createElement('strong'), { textContent: info.name }),
            Object.assign(document.createElement('span'), { textContent: info.spec })] : []));
          if (info && point) {
            const bounds = this.host.getBoundingClientRect();
            const x = Math.max(6, Math.min(point.x - bounds.left + 14, bounds.width - this.tip.offsetWidth - 6));
            this.tip.style.transform = `translate(${Math.round(x)}px, ${Math.round(Math.max(6, point.y - bounds.top - 44))}px)`;
          }
          options.onHover?.(id);
        },
        onReset: () => { this.currentView = 'three-quarter'; },
        onRender: () => this.updateTags(),
      });
      host.append(this.overlay, this.tip);
    } catch (error) {
      this.overlay.remove(); this.tip.remove(); throw error;
    }
  }

  async load(bytes: ArrayBuffer): Promise<void> {
    await this.viewer.load(bytes);
    if (this.disposed) return;
    this.viewer.setFinish('cherry');
    this.viewer.setDisassembly(this.state.explode, false);
    this.viewer.selectAssembly(electricAssemblyForPart(this.state.selected));
    this.ready = true;
  }

  update(state: GuitarLabState, animate = true): void {
    if (this.disposed) return;
    if (state.kind !== 'electric') throw new Error('Switch renderer before leaving the electric model.');
    const previous = this.state; this.state = state;
    if (!this.ready) return;
    if (state.explode !== previous.explode) {
      if (this.currentView === 'headstock' || this.currentView === 'bridge') this.view('three-quarter');
      this.viewer.setDisassembly(state.explode, animate);
    }
    if (state.selected !== previous.selected) this.viewer.selectAssembly(electricAssemblyForPart(state.selected));
  }

  setActive(active: boolean): void {
    this.viewer.setActive(active);
    if (!active && this.ready) { this.viewer.setDisassembly(this.state.explode, false); this.tip.hidden = true; }
  }
  setReducedMotion(enabled: boolean): void { this.viewer.setReducedMotion(enabled); }
  hover(part: GuitarPartId | null): void { this.viewer.hoverAssembly(electricAssemblyForPart(part)); }
  setTurntable(enabled: boolean): void { this.viewer.setTurntable(enabled); }
  get turntable(): boolean { return this.viewer.turntable; }
  get cameraView(): GuitarLabView { return this.currentView; }
  get explodeShown(): number { return this.viewer.disassembly; }
  get rendering(): boolean { return this.viewer.rendering; }
  orbit(direction: number): void { this.viewer.cameraAction(direction < 0 ? 'left' : 'right'); }
  zoom(factor: number): void { this.viewer.cameraAction(factor < 1 ? 'in' : 'out'); }
  resetView(): void { this.currentView = 'three-quarter'; this.viewer.reset(); }
  view(view: GuitarLabView): void {
    this.currentView = view;
    if (view === 'headstock' || view === 'bridge') this.viewer.inspect(view);
    else this.viewer.view(view);
  }

  private updateTags(): void {
    if (this.disposed) return;
    const selected = electricAssemblyForPart(this.state.selected), width = this.host.clientWidth, height = this.host.clientHeight;
    const positions: { tag: HTMLSpanElement; x: number; y: number }[] = [];
    for (const assembly of ELECTRIC_ASSEMBLIES) {
      const tag = this.tags.get(assembly.id)!, point = this.viewer.assemblyScreenPoint(assembly.id);
      tag.hidden = this.viewer.disassembly < .3 || !point;
      if (tag.hidden || !point) continue;
      tag.dataset.selected = String(selected === assembly.id);
      tag.dataset.dim = String(selected !== null && selected !== assembly.id);
      positions.push({ tag, ...point });
    }
    positions.sort((a, b) => a.y - b.y || a.x - b.x);
    const boxes: { left: number; top: number; width: number; height: number }[] = [];
    for (const { tag, x, y } of positions) {
      const w = tag.offsetWidth, h = tag.offsetHeight;
      const left = Math.max(8, Math.min(x, width - w - 8));
      let top = Math.max(30, Math.min(y - h / 2, height - h - 8));
      for (let moves = 0; moves <= boxes.length; moves++) {
        const hit = boxes.find(box => left < box.left + box.width + 4 && box.left < left + w + 4 && top < box.top + box.height + 3 && box.top < top + h + 3);
        if (!hit) break;
        top = hit.top + hit.height + 3;
      }
      boxes.push({ left, top, width: w, height: h });
      tag.style.transform = `translate(${Math.round(left)}px, ${Math.round(top)}px)`;
    }
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true; this.viewer.dispose();
    this.tags.clear(); this.overlay.remove(); this.tip.remove();
  }
}
