import { Box3, BufferAttribute, BufferGeometry, Sphere, Vector3 } from 'three';
import { ELECTRIC_ASSEMBLIES, electricComponentAssembly, type ElectricAssemblyId } from '../theory/electricAssembly';
import { electricFinishGroups, electricMeshComponents, type FinishGroup } from './electricFinish';

export interface ElectricAssemblyGeometry {
  id: ElectricAssemblyId;
  geometry: BufferGeometry;
  triangles: readonly number[];
  groups: FinishGroup[];
}

/** Shared attributes contain all source vertices; bounds must follow the used indices. */
export function boundIndexedElectricGeometry(geometry: BufferGeometry): void {
  const position = geometry.getAttribute('position'), index = geometry.getIndex();
  if (!position || !index) throw new Error('The recovered electric geometry must be indexed.');
  const box = new Box3(), point = new Vector3();
  for (let i = 0; i < index.count; i++) {
    point.fromBufferAttribute(position, index.getX(i));
    box.expandByPoint(point);
  }
  geometry.boundingBox = box;
  geometry.boundingSphere = box.getBoundingSphere(new Sphere());
}

/** Partition complete components, preserving every face, winding, normal and UV. */
export function electricAssemblyGeometry(source: BufferGeometry): ElectricAssemblyGeometry[] {
  const { components } = electricMeshComponents(source), index = source.getIndex()!;
  const byPart = new Map<ElectricAssemblyId, number[]>(ELECTRIC_ASSEMBLIES.map(part => [part.id, []]));
  for (const component of components) byPart.get(electricComponentAssembly(component))!.push(...component.triangles);
  const materials = new Int8Array(index.count / 3);
  for (const group of electricFinishGroups(source)) materials.fill(group.materialIndex, group.start / 3, (group.start + group.count) / 3);
  for (const [id, triangles] of byPart) {
    if (!triangles.length) throw new Error(`The recovered ${id} assembly is missing.`);
  }
  return [...byPart].map(([id, triangles]) => {
    triangles.sort((a, b) => a - b);
    const geometry = new BufferGeometry(), indices = new Uint32Array(triangles.length * 3), groups: FinishGroup[] = [];
    for (const [name, attribute] of Object.entries(source.attributes)) geometry.setAttribute(name, attribute);
    triangles.forEach((triangle, slot) => {
      for (let corner = 0; corner < 3; corner++) indices[slot * 3 + corner] = index.getX(triangle * 3 + corner);
      const materialIndex = materials[triangle], previous = groups[groups.length - 1];
      if (previous?.materialIndex === materialIndex) previous.count += 3;
      else groups.push({ start: slot * 3, count: 3, materialIndex });
    });
    geometry.setIndex(new BufferAttribute(indices, 1));
    groups.forEach(group => geometry.addGroup(group.start, group.count, group.materialIndex));
    boundIndexedElectricGeometry(geometry);
    return { id, geometry, triangles, groups };
  });
}
